//
(function() {
  var saved = localStorage.getItem('theme');
  var prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  if (saved === 'light' || (!saved && !prefersDark)) {
    document.documentElement.setAttribute('data-theme', 'light');
  } else {
    document.documentElement.setAttribute('data-theme', 'dark');
  }
})();
//

head.b:skin:
:root {
  color-scheme: dark;

  --bg-primary: #090a0f;
  --bg-secondary: #12141c;
  --bg-card: rgba(18, 20, 28, 0.75);
  --bg-card-hover: rgba(26, 29, 41, 0.9);
  --bg-glass: rgba(9, 10, 15, 0.88);
  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.18);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-tertiary: #64748b;

  --accent-cyan: #38bdf8;
  --accent-emerald: #10b981;
  --code-bg: #0f1118;
  --selection-bg: #38bdf8;
  --selection-text: #090a0f;

  --font-ui: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

[data-theme='light'] {
  color-scheme: light;

  --bg-primary: #fafbfc;
  --bg-secondary: #ffffff;
  --bg-card: #ffffff;
  --bg-card-hover: #f1f5f9;
  --bg-glass: rgba(250, 251, 252, 0.92);
  --border-subtle: #e2e8f0;
  --border-strong: #cbd5e1;

  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-tertiary: #94a3b8;

  --accent-cyan: #0284c7;
  --accent-emerald: #059669;
  --code-bg: #f1f5f9;
  --selection-bg: #0284c7;
  --selection-text: #ffffff;
}

* { box-sizing: border-box; }

@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

body {
  margin: 0;
  padding: 0;
  width: 100%;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.7;
  overflow-x: hidden;
  overflow-wrap: break-word;
  transition: background-color 0.25s ease, color 0.25s ease;
  background-image: radial-gradient(ellipse at 50% -10%, rgba(56, 189, 248, 0.08) 0%, transparent 60%);
  background-attachment: fixed;
}

@keyframes scrollIndicator {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
.scroll-progress-line {
  position: fixed; top: 0; left: 0; width: 100%; height: 3px;
  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-emerald));
  transform-origin: 0 50%; z-index: 10000;
  animation: scrollIndicator auto linear; animation-timeline: scroll();
}

::view-transition-old(root), ::view-transition-new(root) { animation-duration: 0.22s; }
::selection { background: var(--selection-bg); color: var(--selection-text); }
:focus-visible { outline: 2px solid var(--accent-cyan); outline-offset: 3px; }

/* TELEMETRİ BARI */
.telemetry-banner {
  background: var(--bg-secondary); border-bottom: 1px solid var(--border-subtle);
  font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-secondary); padding: 6px 0;
}
.telemetry-inner {
  max-width: 1320px; width: 92%; margin: 0 auto;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;
}
.telemetry-item { display: inline-flex; align-items: center; gap: 6px; }
.status-dot-pulse {
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent-emerald);
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.8); animation: pulseAnim 2s infinite;
}
@keyframes pulseAnim {
  0% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.2); }
  100% { opacity: 1; transform: scale(1); }
}

/* HEADER */
header {
  position: sticky; top: 0; z-index: 999;
  background: var(--bg-glass);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border-bottom: 1px solid var(--border-subtle);
}
.header-container {
  max-width: 1320px; width: 92%; margin: 0 auto; padding: 12px 0;
  display: flex; justify-content: space-between; align-items: center; gap: 15px;
}

.brand { display: flex; align-items: center; gap: 10px; }
.brand-logo {
  font-size: 1.35rem; font-weight: 800; letter-spacing: -0.5px;
  color: var(--text-primary); text-decoration: none;
}
.brand-tag {
  font-family: var(--font-mono); font-size: 0.7rem; font-weight: 700;
  background: rgba(56, 189, 248, 0.12); color: var(--accent-cyan);
  padding: 3px 8px; border-radius: 4px; border: 1px solid rgba(56, 189, 248, 0.25);
}

.header-actions { display: flex; align-items: center; gap: 10px; }
.cli-pill {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  color: var(--text-secondary); font-family: var(--font-mono); font-size: 0.75rem;
  padding: 6px 12px; border-radius: 6px; cursor: pointer; transition: all 0.2s;
}
.cli-pill:hover { border-color: var(--accent-cyan); color: var(--text-primary); }
.kbd-key {
  background: var(--border-subtle); color: var(--text-primary);
  padding: 1px 5px; border-radius: 3px; font-size: 0.68rem;
}

.theme-button {
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  color: var(--text-primary); border-radius: 6px; padding: 6px 12px;
  font-size: 0.82rem; font-weight: 700; cursor: pointer; transition: all 0.2s;
}
.theme-button:hover { border-color: var(--text-primary); }

/* ============================================================
   HEADER NAVİGASYONU & SEKMELER (MİNİMALİST MONO TABS)
   ============================================================ */
.header-nav {
  display: flex; align-items: center; gap: 4px;
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  border-radius: 8px; padding: 4px;
}
.nav-item {
  appearance: none; -webkit-appearance: none;
  background: transparent; border: 1px solid transparent;
  color: var(--text-secondary); font-family: var(--font-mono); font-size: 0.8rem;
  font-weight: 600; padding: 6px 14px; border-radius: 6px; cursor: pointer;
  transition: all 0.18s ease; text-decoration: none; white-space: nowrap;
}
.nav-item:hover { color: var(--text-primary); }
.nav-item.active {
  background: var(--bg-card); color: var(--accent-cyan);
  border-color: var(--border-strong); font-weight: 700;
  box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

/* SEKME İÇERİK PANELLERİ */
.main-wrap { max-width: 1320px; width: 92%; margin: 0 auto; padding: 30px 0 60px 0; }

.tab-pane {
  display: none;
  animation: tabFade 0.22s ease-out forwards;
}
.tab-pane.active { display: block; }
@keyframes tabFade {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* TEKİL POST SAYFASINDA OTOMATİK DÜZEN */
body.is-post-page .header-nav { display: none; }

/* HERO & BENTO */
.hero-box { margin-bottom: 50px; }
.hero-eyebrow {
  font-family: var(--font-mono); font-size: 0.85rem; font-weight: 700;
  color: var(--accent-cyan); display: inline-flex; align-items: center; gap: 6px; margin-bottom: 12px;
}
.hero-title {
  font-size: clamp(2.1rem, 5vw, 3.4rem); font-weight: 800; line-height: 1.15;
  letter-spacing: -1.2px; margin: 0 0 18px 0; color: var(--text-primary);
}
.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.15rem); color: var(--text-secondary);
  max-width: 840px; line-height: 1.8; margin-bottom: 30px;
}

.bento-grid {
  display: grid; grid-template-columns: repeat(12, 1fr); gap: 20px; margin-bottom: 40px;
}
.bento-card {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 12px; padding: 26px; backdrop-filter: blur(12px);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  position: relative; overflow: hidden;
}
.bento-card:hover {
  transform: translateY(-3px); border-color: var(--border-strong);
  box-shadow: 0 12px 30px rgba(0,0,0,0.25);
}
.bento-card.col-7 { grid-column: span 7; }
.bento-card.col-5 { grid-column: span 5; }

.bento-icon {
  font-family: var(--font-mono); font-size: 0.8rem; font-weight: 700;
  display: inline-block; padding: 4px 10px; border-radius: 6px;
  margin-bottom: 16px; background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle);
}
.bento-title { font-size: 1.25rem; font-weight: 700; margin: 0 0 10px 0; color: var(--text-primary); }
.bento-desc { font-size: 0.92rem; color: var(--text-secondary); line-height: 1.65; margin: 0 0 16px 0; }
.bento-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.b-tag {
  font-family: var(--font-mono); font-size: 0.72rem; font-weight: 600;
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  padding: 3px 8px; border-radius: 4px; color: var(--text-secondary);
}

.section-head {
  display: flex; justify-content: space-between; align-items: flex-end;
  border-bottom: 1px solid var(--border-subtle); padding-bottom: 16px; margin-bottom: 30px;
}
.section-head h2 {
  font-size: 1.8rem; font-weight: 800; letter-spacing: -0.5px; margin: 0; color: var(--text-primary);
}
.section-head h2 span { font-family: var(--font-mono); color: var(--accent-cyan); font-weight: 400; }

/* BLOG KARTLARI */
.archive-select-box {
  width: 100%; padding: 14px; border: 1px solid var(--border-subtle); border-radius: 8px;
  background: var(--bg-secondary); color: var(--text-primary); font-family: var(--font-mono);
  font-weight: 700; margin-bottom: 25px; outline: none;
}

.article-card {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 30px; margin-bottom: 25px; transition: border-color 0.2s, transform 0.2s;
}
.article-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.article-date {
  font-family: var(--font-mono); font-size: 0.75rem; font-weight: 700;
  color: var(--accent-cyan); display: inline-block; margin-bottom: 12px;
}
.article-title {
  font-size: 1.6rem; font-weight: 800; line-height: 1.35; color: var(--text-primary) !important;
  text-decoration: none; display: block; margin-bottom: 16px; letter-spacing: -0.4px;
}
.article-title:hover { color: var(--accent-cyan) !important; }
.article-content { color: var(--text-secondary); line-height: 1.85; font-size: 1.02rem; }
.article-content img {
  max-width: 100%; height: auto; border-radius: 8px; border: 1px solid var(--border-subtle); margin: 25px 0;
}
.article-content a { color: var(--accent-cyan); text-decoration: underline; text-underline-offset: 4px; }

pre {
  background: var(--code-bg); border: 1px solid var(--border-subtle);
  border-radius: 8px; padding: 20px; font-family: var(--font-mono);
  font-size: 0.88rem; overflow-x: auto; margin: 25px 0;
}
code { font-family: var(--font-mono); }

.page-nav { display: flex; justify-content: space-between; margin-top: 40px; }
.nav-btn {
  font-family: var(--font-mono); font-size: 0.85rem; font-weight: 700;
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  color: var(--text-primary) !important; text-decoration: none; padding: 10px 18px; border-radius: 6px;
  transition: all 0.2s; cursor: pointer; display: inline-flex; align-items: center; justify-content: center;
}
.nav-btn:hover { border-color: var(--text-primary); }

/* FOTOĞRAF GALERİSİ */
#album-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 24px; margin-bottom: 30px;
}
.gallery-album-card {
  background: var(--bg-card); border: 1px solid var(--border-subtle); border-radius: 10px;
  padding: 12px; cursor: pointer; transition: all 0.25s ease;
}
.gallery-album-card:hover {
  transform: translateY(-4px); border-color: var(--accent-cyan);
  box-shadow: 0 10px 25px rgba(0,0,0,0.2);
}
.gallery-album-card img {
  width: 100%; height: 200px; object-fit: cover; border-radius: 6px;
  border: 1px solid var(--border-subtle); aspect-ratio: 16/10;
}
.gallery-album-title {
  font-size: 0.95rem; font-weight: 700; margin-top: 12px; text-align: center;
}

#photos-container {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 25px;
}
.photo-cell {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 12px; transition: transform 0.2s, border-color 0.2s;
}
.photo-cell:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.photo-cell img {
  width: 100%; aspect-ratio: 4/3; object-fit: cover; border-radius: 6px;
  cursor: zoom-in; display: block; background: var(--bg-secondary);
}
.exif-telemetry-hud {
  margin-top: 12px; background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  border-radius: 6px; padding: 8px 12px; font-family: var(--font-mono); font-size: 0.72rem;
  color: var(--text-secondary); line-height: 1.5; min-height: 48px;
}
.exif-cam { color: var(--text-primary); font-weight: 700; display: block; margin-bottom: 2px; }

/* NATIVE MODAL */
dialog.photo-modal-native {
  border: none; padding: 0; background: transparent; max-width: 95vw; max-height: 95vh;
  color: var(--text-primary); overflow: visible;
  transition: opacity 0.25s ease, transform 0.25s ease, overlay 0.25s ease allow-discrete, display 0.25s ease allow-discrete;
  opacity: 0; transform: scale(0.96);
}
dialog.photo-modal-native[open] { opacity: 1; transform: scale(1); }
@starting-style {
  dialog.photo-modal-native[open] { opacity: 0; transform: scale(0.96); }
}
dialog.photo-modal-native::backdrop {
  background-color: rgba(0, 0, 0, 0.88); backdrop-filter: blur(12px);
  transition: background-color 0.25s ease, backdrop-filter 0.25s ease, overlay 0.25s ease allow-discrete, display 0.25s ease allow-discrete;
}
.modal-frame { display: flex; flex-direction: column; align-items: center; position: relative; }
.modal-frame img {
  max-width: 92vw; max-height: 75vh; object-fit: contain; border-radius: 8px;
  border: 1px solid var(--border-subtle); box-shadow: 0 20px 50px rgba(0,0,0,0.7);
}
.modal-bottom-hud {
  margin-top: 16px; background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  border-radius: 8px; padding: 12px 20px; width: 100%; max-width: 650px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 15px;
}
.modal-hud-text { font-family: var(--font-mono); font-size: 0.8rem; }
.modal-hud-controls { display: flex; gap: 8px; }
.hud-control-btn {
  font-family: var(--font-mono); font-size: 0.78rem; font-weight: 700;
  background: var(--bg-card); border: 1px solid var(--border-subtle); color: var(--text-primary);
  padding: 6px 14px; border-radius: 6px; cursor: pointer; transition: all 0.15s;
}
.hud-control-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.modal-close-round {
  position: absolute; top: -14px; right: -14px; background: var(--text-primary); color: var(--bg-primary);
  border: none; border-radius: 50%; width: 32px; height: 32px; font-weight: 800; cursor: pointer;
  display: flex; align-items: center; justify-content: center; font-size: 1.1rem;
}

dialog.cli-palette {
  background: var(--bg-secondary); border: 1px solid var(--border-strong);
  border-radius: 12px; width: 92vw; max-width: 620px; color: var(--text-primary);
  padding: 0; box-shadow: 0 25px 60px rgba(0,0,0,0.6); overflow: hidden;
}
.cli-bar {
  background: var(--bg-primary); border-bottom: 1px solid var(--border-subtle);
  padding: 12px 18px; display: flex; justify-content: space-between; align-items: center;
  font-family: var(--font-mono); font-size: 0.8rem;
}
.cli-content { padding: 18px; font-family: var(--font-mono); font-size: 0.85rem; }
.cli-log {
  max-height: 320px; overflow-y: auto; margin-bottom: 15px; white-space: pre-wrap; line-height: 1.6;
}
.cli-input-wrapper { display: flex; align-items: center; gap: 10px; }
.cli-prefix { color: var(--accent-emerald); font-weight: 800; }
.cli-type-input {
  width: 100%; background: transparent; border: none; outline: none;
  color: var(--text-primary); font-family: var(--font-mono); font-size: 0.9rem;
}

.form-box {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 12px; padding: 35px; max-width: 680px;
}
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block; font-family: var(--font-mono); font-size: 0.8rem; font-weight: 700;
  color: var(--text-secondary); margin-bottom: 8px;
}
.form-group input, .form-group textarea {
  width: 100%; padding: 14px 16px; border: 1px solid var(--border-subtle);
  border-radius: 8px; background: var(--bg-secondary); color: var(--text-primary);
  font-family: inherit; font-size: 0.95rem; outline: none; transition: border-color 0.2s;
}
.form-group input:focus, .form-group textarea:focus { border-color: var(--accent-cyan); }
.submit-cta {
  font-family: var(--font-mono); font-weight: 700; font-size: 0.95rem;
  background: var(--text-primary); color: var(--bg-primary); border: none;
  padding: 14px 28px; border-radius: 6px; cursor: pointer; transition: opacity 0.2s; width: 100%;
}
.submit-cta:hover { opacity: 0.9; }

.resume-container {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 12px; padding: 35px; margin-bottom: 30px;
}
.resume-section-item { margin-bottom: 32px; }
.resume-section-item:last-child { margin-bottom: 0; }
.resume-title {
  font-size: 1.25rem; font-weight: 700; color: var(--text-primary);
  border-bottom: 1px solid var(--border-subtle); padding-bottom: 8px; margin: 0 0 14px 0;
  display: flex; align-items: center; gap: 8px;
}
.resume-title span { font-family: var(--font-mono); color: var(--accent-cyan); font-weight: 400; font-size: 1rem; }
.resume-text {
  color: var(--text-secondary); line-height: 1.85; font-size: 1.02rem; margin: 0;
}
.resume-text strong { color: var(--text-primary); }
.skills-cluster {
  margin-top: 30px; display: flex; flex-wrap: wrap; gap: 10px;
}
.skill-badge {
  background: var(--bg-secondary); border: 1px solid var(--border-subtle);
  color: var(--text-primary); padding: 8px 16px; border-radius: 20px;
  font-family: var(--font-mono); font-size: 0.8rem; font-weight: 700;
  transition: all 0.2s ease; cursor: default;
}

.social-links-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px;
  margin-bottom: 35px;
}
.social-card {
  background: var(--bg-card); border: 1px solid var(--border-subtle);
  border-radius: 10px; padding: 16px 20px; display: flex; align-items: center; gap: 16px;
  text-decoration: none; color: var(--text-primary); transition: all 0.2s ease;
}
.social-card:hover {
  border-color: var(--accent-cyan); transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(0,0,0,0.15);
}
.social-icon { color: var(--accent-cyan); flex-shrink: 0; }
.social-meta { display: flex; flex-direction: column; }
.social-label { font-size: 0.95rem; font-weight: 700; color: var(--text-primary); }
.social-val { font-family: var(--font-mono); font-size: 0.76rem; color: var(--text-tertiary); }

.skill-badge:hover {
  background: var(--text-primary); color: var(--bg-primary); border-color: var(--text-primary);
  transform: translateY(-2px);
}


footer {
  border-top: 1px solid var(--border-subtle); padding: 50px 0; text-align: center;
  font-size: 0.88rem; color: var(--text-tertiary);
}
.footer-inner { max-width: 1320px; width: 92%; margin: 0 auto; }

@media (max-width: 960px) {
  .bento-card.col-7, .bento-card.col-5 { grid-column: span 12; }
  .brand-tag { display: none; }
  .header-nav { order: 3; width: 100%; overflow-x: auto; scrollbar-width: none; }
  .header-nav::-webkit-scrollbar { display: none; }
  .nav-item { flex: 1 1 auto; text-align: center; padding: 6px 10px; font-size: 0.75rem; }
}

body.script:
//
  document.getElementById('currentYear').innerText = new Date().getFullYear();

  // ============================================
  // SEKMELİ YAPI KONTROL MOTORU (TAB SWITCHER)
  // ============================================
  function switchTab(tabId) {
    var validTabs = ['altyapi', 'ozgecmis', 'gunluk', 'fotograflar', 'iletisim'];
    if (validTabs.indexOf(tabId) === -1) return;

    function renderTab() {
      var panes = document.querySelectorAll('.tab-pane');
      for (var i = 0; i < panes.length; i++) {
        panes[i].classList.remove('active');
      }

      var triggers = document.querySelectorAll('.nav-item');
      for (var j = 0; j < triggers.length; j++) {
        var isCurrent = triggers[j].getAttribute('data-tab') === tabId;
        triggers[j].classList.toggle('active', isCurrent);
        triggers[j].setAttribute('aria-selected', isCurrent ? 'true' : 'false');
      }

      var activePane = document.getElementById('tab-' + tabId);
      if (activePane) activePane.classList.add('active');

      if (window.location.hash !== '#' + tabId) {
        history.replaceState(null, '', '#' + tabId);
      }
    }

    if (document.startViewTransition && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      document.startViewTransition(renderTab);
    } else {
      renderTab();
    }
  }

  // URL Hash veya Post Sayfasına Göre Otomatik Sekme Seçimi
  window.addEventListener('DOMContentLoaded', function() {
    var hash = window.location.hash.replace('#', '');
    var isPost = document.body.classList.contains('is-post-page');

    if (isPost) {
      switchTab('gunluk');
    } else if (['altyapi', 'ozgecmis', 'gunluk', 'fotograflar', 'iletisim'].indexOf(hash) !== -1) {
      switchTab(hash);
    } else {
      switchTab('altyapi');
    }
  });

  // ============================================
  // VIEW TRANSITIONS API İLE TEMA YÖNETİMİ
  // ============================================
  var themeBtn = document.getElementById('themeBtn');
  var metaTheme = document.getElementById('meta-theme-color');

  function syncThemeUI() {
    var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    if (themeBtn) themeBtn.innerText = isDark ? 'MOD: KOYU' : 'MOD: AÇIK';
    if (metaTheme) metaTheme.setAttribute('content', isDark ? '#090a0f' : '#fafbfc');
  }

  function changeTheme(themeName) {
    document.documentElement.setAttribute('data-theme', themeName);
    localStorage.setItem('theme', themeName);
    syncThemeUI();
  }

  function toggleTheme() {
    var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    var target = isDark ? 'light' : 'dark';

    if (!document.startViewTransition || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      changeTheme(target);
    } else {
      document.startViewTransition(function() { changeTheme(target); });
    }
  }
  syncThemeUI();

  // ============================================
  // FLICKR MOTORU & TELEMETRİ ÖNBELLEĞİ
  // ============================================
  var apiKey = "3954ec9c533459f470080bf24178df16"; 
  var userID = "204447030@N04"; 
  var exifStore = new Map();
  var photoList = [];
  var activePhotoIdx = 0;

  document.addEventListener('DOMContentLoaded', fetchFlickrAlbums);

  async function fetchFlickrAlbums() {
    var grid = document.getElementById('album-grid');
    var url = "https://www.flickr.com/services/rest/?method=flickr.photosets.getList&api_key=" + apiKey + "&user_id=" + userID + "&format=json&nojsoncallback=1";

    try {
      var res = await fetch(url);
      var data = await res.json();

      if (data.photosets && data.photosets.photoset) {
        var html = "";
        data.photosets.photoset.forEach(function(set) {
          var thumb = "https://live.staticflickr.com/" + set.server + "/" + set.primary + "_" + set.secret + "_z.jpg";
          var title = escapeText(set.title._content);
          html += '<div class=\"gallery-album-card\" role=\"button\" tabindex=\"0\" onclick=\"displayAlbumPhotos(\'' + set.id + '\')" onkeydown=\"if(event.key===\'Enter\'||event.key===\' \')displayAlbumPhotos(\'' + set.id + '\')\">' +
                     '<img loading=\"lazy\" src=\"' + thumb + '\" alt=\"' + title + '\" width=\"290\" height=\"180\"/>' +
                     '<div class=\"gallery-album-title\">' + title + '</div>' +
                   '</div>';
        });
        grid.innerHTML = html;
      } else {
        grid.innerHTML = "/Hata: Albümler sunucudan alınamadı.";
      }
    } catch (err) {
      grid.innerHTML = "/Hata: Flickr bağlantısı kurulamadı.";
    }
  }

  function showAlbums() {
    document.getElementById('photo-view').style.display = 'none';
    document.getElementById('album-view').style.display = 'block';
  }

  async function displayAlbumPhotos(setID) {
    document.getElementById('album-view').style.display = 'none'; 
    var photoView = document.getElementById('photo-view');
    var container = document.getElementById('photos-container');
    photoView.style.display = 'block'; 
    container.innerHTML = "/Görseller indeksleniyor...";

    var url = "https://www.flickr.com/services/rest/?method=flickr.photosets.getPhotos&api_key=" + apiKey + "&photoset_id=" + setID + "&user_id=" + userID + "&format=json&nojsoncallback=1";

    try {
      var res = await fetch(url);
      var data = await res.json();

      if (data.photoset && data.photoset.photo) {
        photoList = data.photoset.photo;
        var html = "";
        photoList.forEach(function(photo, idx) {
          var thumb = "https://live.staticflickr.com/" + photo.server + "/" + photo.id + "_" + photo.secret + "_z.jpg";
          html += '<div class=\"photo-cell\" data-photo-id=\"' + photo.id + '\">' +
                    '<img loading=\"lazy\" src=\"' + thumb + '\" alt=\"Ozan Özdil Orta Format\" onclick=\"openPhotoModal(' + idx + ')\" width=\"340\" height=\"255\"/>' +
                    '<div class=\"exif-telemetry-hud\" id=\"exif-' + photo.id + '\">[Telemetri Taranıyor...]</div>' +
                  '</div>';
        });
        container.innerHTML = html;
        attachExifObserver();
      }
    } catch (err) {
      container.innerHTML = "/Hata: Fotoğraflar alınamadı.";
    }
  }

  function attachExifObserver() {
    if (!('IntersectionObserver' in window)) return;
    var obs = new IntersectionObserver(function(entries, observer) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          var pid = entry.target.getAttribute('data-photo-id');
          if (pid) {
            getExifTelemetry(pid, 'exif-' + pid);
            observer.unobserve(entry.target);
          }
        }
      });
    }, { rootMargin: '120px' });

    document.querySelectorAll('.photo-cell').forEach(function(cell) { obs.observe(cell); });
  }

  async function getExifTelemetry(photoID, targetDomId) {
    var el = targetDomId ? document.getElementById(targetDomId) : null;

    if (exifStore.has(photoID)) {
      var val = exifStore.get(photoID);
      if (el) el.innerHTML = val;
      return val;
    }

    var url = "https://www.flickr.com/services/rest/?method=flickr.photos.getExif&api_key=" + apiKey + "&photo_id=" + photoID + "&format=json&nojsoncallback=1";
    try {
      var res = await fetch(url);
      var data = await res.json();
      if (data.photo && data.photo.exif) {
        var iso = "-", f = "-", s = "-", camera = "-", lens = "-";
        data.photo.exif.forEach(function(e) {
          if (e.tag === "Model") camera = e.raw._content;
          if (e.tag === "LensModel") lens = e.raw._content;
          if (e.tag === "ISO") iso = e.raw._content;
          if (e.tag === "FNumber") f = "f/" + e.raw._content;
          if (e.tag === "ExposureTime") s = e.raw._content + "s";
        });
        var hudHtml = '<span class=\"exif-cam\">' + camera + '</span>' + lens + ' &#8226; ' + f + ' &#8226; ' + s + ' &#8226; ISO ' + iso;
        exifStore.set(photoID, hudHtml);
        if (el) el.innerHTML = hudHtml;
        return hudHtml;
      }
    } catch (err) {}
    var fallback = "[EXIF TEMİZLENMİŞ]";
    exifStore.set(photoID, fallback);
    if (el) el.innerText = fallback;
    return fallback;
  }

  // ============================================
  // NATIVE <dialog> MODAL VE KLAVYE YÖNETİMİ
  // ============================================
  var pModal = document.getElementById('photoModal');

  async function openPhotoModal(index) {
    if (!photoList[index]) return;
    activePhotoIdx = index;
    var p = photoList[index];
    var fullUrl = "https://live.staticflickr.com/" + p.server + "/" + p.id + "_" + p.secret + "_b.jpg";

    document.getElementById('photoModalImg').src = fullUrl;
    var exifArea = document.getElementById('photoModalExif');
    exifArea.innerText = "Metadata okunuyor...";

    if (typeof pModal.showModal === "function") {
      pModal.showModal();
    } else {
      pModal.setAttribute('open', '');
    }

    var info = await getExifTelemetry(p.id);
    exifArea.innerHTML = info;
  }

  function closePhotoModal() {
    if (typeof pModal.close === "function") {
      pModal.close();
    } else {
      pModal.removeAttribute('open');
    }
    document.getElementById('photoModalImg').src = '';
  }

  function shiftPhoto(offset) {
    var next = activePhotoIdx + offset;
    if (next < 0) next = photoList.length - 1;
    if (next >= photoList.length) next = 0;
    openPhotoModal(next);
  }

  pModal.addEventListener('click', function(e) {
    var r = pModal.getBoundingClientRect();
    var inside = (r.top <= e.clientY && e.clientY <= r.top + r.height && r.left <= e.clientX && e.clientX <= r.left + r.width);
    if (!inside) closePhotoModal();
  });

  // ============================================
  // TERMINAL COMMAND PALETTE (CTRL+K)
  // ============================================
  var cliDlg = document.getElementById('cliDialog');
  var cliIn = document.getElementById('cliCommand');
  var cliLog = document.getElementById('cliLog');

  function openCLI() {
    if (typeof cliDlg.showModal === "function") {
      cliDlg.showModal();
    } else {
      cliDlg.setAttribute('open', '');
    }
    setTimeout(function() { cliIn.focus(); }, 50);
  }

  function closeCLI() {
    if (typeof cliDlg.close === "function") {
      cliDlg.close();
    } else {
      cliDlg.removeAttribute('open');
    }
  }

  document.addEventListener('keydown', function(e) {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      if (cliDlg.open) closeCLI(); else openCLI();
    }
    if (pModal.open) {
      if (e.key === 'ArrowLeft') shiftPhoto(-1);
      if (e.key === 'ArrowRight') shiftPhoto(1);
    }
  });

  cliIn.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
      var cmd = cliIn.value.trim().toLowerCase();
      cliIn.value = '';
      runCLI(cmd);
    }
  });

  function runCLI(cmd) {
    var text = '> ' + cmd + '\n';
    switch(cmd) {
      case 'help':
        text += 'Komutlar:\n- neofetch : Sistem ve donanım özellikleri\n- whoami   : Ozan Özdil profili\n- altyapi  : Altyapı ve mimari sekmesine git\n- photos   : Galeri sekmesine git\n- blog     : Günlük sekmesine git\n- contact  : İletişim sekmesine git\n- theme    : Koyu/Açık tema değiştir\n- clear    : Ekranı temizle\n- exit     : Terminali kapat';
        break;
      case 'whoami':
        text += 'Ozan Özdil\nSistem Mühendisi & Altyapı Mimarı\nZero-Trust & Homelab Güvenliği | Fujifilm Orta Format Fotoğrafçı';
        break;
      case 'neofetch':
        text += 'OS: CachyOS & Omarchy Linux x86_64 (Kernel 6.x BORE)\nShell: Antigravity CLI / Fish\nInfrastructure: TrueNAS SCALE + Docker Microservices\nNetwork: OPNsense + Omada Zero-Trust Topoloji [ozdil.cloud]\nOptics: Fujifilm GFX 100S / GFX 50R (102MP Medium Format)\nSimulation: Assetto Corsa Competizione (ACC) on Wayland';
        break;
      case 'theme':
        toggleTheme();
        text += 'Tema modu güncellendi.';
        break;
      case 'ozgecmis':
      case 'hakkimda':
      case 'about':
        closeCLI();
        switchTab('ozgecmis');
        return;
      case 'altyapi':
        closeCLI();
        switchTab('altyapi');
        return;
      case 'photos':
      case 'fotograflar':
        closeCLI();
        switchTab('fotograflar');
        return;
      case 'blog':
      case 'gunluk':
        closeCLI();
        switchTab('gunluk');
        return;
      case 'contact':
      case 'iletisim':
        closeCLI();
        switchTab('iletisim');
        return;
      case 'clear':
        cliLog.innerText = '';
        return;
      case 'exit':
        closeCLI();
        return;
      default:
        text += 'Bilinmeyen komut: \'' + cmd + '\'. Yardım için \'help\' yazın.';
    }
    cliLog.innerText += '\n' + text + '\n';
    cliLog.scrollTop = cliLog.scrollHeight;
  }

  function escapeText(str) {
    return str.replace(/[&<>'"]/g, function(t) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[t] || t;
    });
  }
